style.css:
@-moz-document domain("chat.google.com") {
:root {
    --mdc-theme-primary: #c084fc !important;
    --mdc-theme-secondary: #e9d5ff !important;
  }

  a, a:visited, a:hover,
  .R8G2F, .zTETae, .UQuaGc, .z38b6, .VfPpkd-dgl2Hf-ppHlrf-sM5MNb {
    color: #c084fc !important;
    transition: color 0.3s ease;
  }

  a:hover, .R8G2F:hover, .zTETae:hover {
    text-shadow: 0 0 8px rgba(192, 132, 252, 0.5);
  }

  .VfPpkd-Bz112c-LgbsSe {
    background: linear-gradient(135deg, #d8b4fe, #c084fc) !important;
    border: none !important;
    color: white !important;
    transition: all 0.3s ease;
    box-shadow: 0 0 8px rgba(192, 132, 252, 0.3);
  }

  .VfPpkd-Bz112c-LgbsSe:hover {
    box-shadow: 0 0 15px rgba(192, 132, 252, 0.6);
    transform: scale(1.02);
  }

  .VfPpkd-kBDsod {
    background-color: rgba(192, 132, 252, 0.15) !important;
    border-radius: 8px !important;
    transition: background-color 0.3s ease;
  }
}
